import re


def eval_expression(expr):
    # Tokenize the expression to handle numbers (including negative), operators, and parentheses
    # This regex captures numbers (integers/decimals), operators, and parentheses
    tokens = re.findall(r"-?\d+\.?\d*|\+|\-|\*|\/|\(|\)", expr)

    # Validate that we actually found tokens and didn't leave anything out
    reconstructed = "".join(tokens)
    if reconstructed != expr.replace(" ", ""):
        raise ValueError("Invalid characters in expression")

    # Shunting-yard algorithm to convert infix to Postfix (RPN)
    def to_rpn(tokens):
        output = []
        operators = []
        precedence = {"+": 1, "-": 1, "*": 2, "/": 2}

        expect_operand = True  # Used to distinguish unary minus from binary minus

        for i, token in enumerate(tokens):
            if token == "(":
                operators.append(token)
                expect_operand = True
            elif token == ")":
                while operators and operators[-1] != "(":
                    output.append(operators.pop())
                if not operators:
                    raise ValueError("Mismatched parentheses")
                operators.pop()  # Remove '('
                expect_operand = False
            elif token in precedence:
                # Handle unary minus (e.g., "-3" or "(-5)")
                if token == "-" and expect_operand:
                    # Treat as a negative number by consuming the next token
                    if i + 1 < len(tokens):
                        next_token = tokens[i + 1]
                        output.append(
                            str(-float(next_token)
                                if "." in next_token
                                else -int(next_token))
                        )
                        tokens[i + 1] = (
                            None  # Mark next token as processed (skip it in next loop)
                        )
                        expect_operand = False
                        continue
                    else:
                        raise ValueError("Trailing operator")

                while (
                    operators
                    and operators[-1] != "("
                    and precedence.get(operators[-1], 0) >= precedence[token]
                ):
                    output.append(operators.pop())
                operators.append(token)
                expect_operand = True
            elif token is None:
                continue
            else:  # It's a number
                output.append(
                    float(token) if "." in token else int(token)
                )
                expect_operand = False

        while operators:
            op = operators.pop()
            if op == "(":
                raise ValueError("Mismatched parentheses")
            output.append(op)

        return output

    # Evaluate RPN expression
    def eval_rpn(rpn):
        stack = []
        for token in rpn:
            if isinstance(token, (int, float)):
                stack.append(token)
            else:
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
                b = stack.pop()
                a = stack.pop()

                if token == "+":
                    stack.append(a + b)
                elif token == "-":
                    stack.append(a - b)
                elif token == "*":
                    stack.append(a * b)
                elif token == "/":
                    if b == 0:
                        raise ZeroDivisionError("division by zero")
                    stack.append(a / b)

        if len(stack) != 1:
            raise ValueError("Invalid expression")

        result = stack[0]
        # Return as int if it's a whole number, otherwise float
        return int(result) if result == int(result) else result

    rpn_tokens = to_rpn(tokens)
    return eval_rpn(rpn_tokens)


# --- Example Usage ---
if __name__ == "__main__":
    print(eval_expression("3 + 4 * (2 - 1)"))  # Output: 7
    print(eval_expression("-5 + 10 * (-2)"))  # Output: -25
    print(eval_expression("10 / (5 - 5)"))  # Raises ZeroDivisionError
